275	    /**
276	     * The owner's age band, derived on read from {@code birthDate} against the
277	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18, {@code 'ADULT'}
278	     * from 18 to 64, and {@code 'SENIOR'} at 65 or older. The age is the number of whole years
279	     * between the birth date and the registration date (falling back to the current date when no
280	     * registration date is set).
281	     *
282	     * @return the age band, or {@code null} when no {@code birthDate} is set
283	     */
284	    @Transient
285	    public String getAgeBand() {
286	        if (this.birthDate == null) {
287	            return null;
288	        }
289	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
290	        int age = Period.between(this.birthDate, reference).getYears();
291	        if (age < 18) {
292	            return "MINOR";
293	        }
294	        if (age < 65) {
295	            return "ADULT";
296	        }
297	        return "SENIOR";
298	    }
299	
300	    /**
301	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
302	     * digits contained in the owner's {@code customerCode}.
303	     *
304	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
305	     */
306	    @Transient
307	    public Integer getCheckDigit() {
308	        if (this.customerCode == null) {
309	            return null;
310	        }
311	        int sum = 0;
312	        boolean dbl = true;
313	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
314	            char c = this.customerCode.charAt(i);
315	            if (c < '0' || c > '9') {
316	                continue;
317	            }
318	            int d = c - '0';
319	            if (dbl) {
320	                d *= 2;
321	                if (d > 9) {
322	                    d -= 9;
323	                }
324	            }
325	            sum += d;
326	            dbl = !dbl;
327	        }
328	        return (10 - (sum % 10)) % 10;
329	    }
330	
331	    /**
332	     * The owner's stored E.164 {@code telephone} formatted for humans, derived on read: the
333	     * leading {@code '+'} and country code, a space, then the national digits grouped in threes
334	     * (e.g. {@code '+61 412 345 678'} for a stored {@code '+61412345678'}). The recognised
335	     * country codes are {@code '+61'} (Australia) and {@code '+1'} (NANP); any other prefix falls
336	     * back to a two-digit country code. The raw {@code telephone} is left in E.164 form.
337	     *
338	     * @return the human-formatted telephone, or the raw value when it is not in E.164 form
339	     */
340	    @Transient
341	    public String getTelephoneDisplay() {
342	        if (this.telephone == null || !this.telephone.startsWith("+")
343	                || !this.telephone.substring(1).matches("[0-9]+")) {
344	            return this.telephone;
345	        }
346	        String digits = this.telephone.substring(1);
347	        String countryCode;
348	        if (digits.startsWith("61")) {
349	            countryCode = "61";
350	        } else if (digits.startsWith("1")) {
351	            countryCode = "1";
352	        } else {
353	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
354	        }
355	        String national = digits.substring(countryCode.length());
356	        StringBuilder display = new StringBuilder("+").append(countryCode);
357	        for (int i = 0; i < national.length(); i += 3) {
358	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
359	        }
360	        return display.toString();
361	    }
362	
363	    /**
364	     * The owner's derived duplicate-detection key: the single consolidated identity used to
365	     * detect duplicate owners on create. It is formed as
366	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} from the
367	     * owner's already-normalized {@code telephone} (E.164 form), its lower-cased {@code email}
368	     * (empty when absent) and its assigned {@code householdId}. Two owners are duplicates only
369	     * when their whole {@code identityKey} values are equal.
370	     *
371	     * @return the consolidated identity key
372	     */
373	    @Transient
374	    public String getIdentityKey() {
375	        String telephonePart = this.telephone == null ? "" : this.telephone;
376	        String emailPart = this.email == null ? "" : this.email;
377	        String householdPart = this.householdId == null ? "" : this.householdId;
378	        return telephonePart + "|" + emailPart + "|" + householdPart;
379	    }
