124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
127	        normalizeAddress(ownerFieldsDto);
128	        validateRequiredFields(ownerFieldsDto);
129	        validatePostcode(ownerFieldsDto);
130	        normalizeTelephone(ownerFieldsDto);
131	        normalizeEmail(ownerFieldsDto);
132	        rejectDuplicateIdentity(ownerFieldsDto);
133	        rejectDuplicateHousehold(ownerFieldsDto);
134	        rejectCityAtCapacity(ownerFieldsDto.getCity());
135	        rejectFutureRegistrationDate(ownerFieldsDto);
136	        defaultRegistrationDate(ownerFieldsDto);
137	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        assignCustomerCode(owner);
141	        assignHouseholdId(owner);
142	        assignHouseholdMemberCount(owner);
143	        assignNamesakeCount(owner);
144	        assignMembershipNumber(owner);
145	        assignBulkSignupWarning(owner);
146	        assignPossibleDuplicate(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
147	        this.clinicService.saveOwner(owner);
148	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
149	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
