158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        normalizeEmail(ownerFieldsDto);
164	        currentOwner.setAddress(ownerFieldsDto.getAddress());
165	        currentOwner.setCity(ownerFieldsDto.getCity());
166	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
167	        currentOwner.setLastName(ownerFieldsDto.getLastName());
168	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
169	        currentOwner.setEmail(ownerFieldsDto.getEmail());
170	        this.clinicService.saveOwner(currentOwner);
171	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
172	    }
