238	    /**
239	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
240	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
241	     * Validation already rejects {@code null} values and the pattern-constrained fields
242	     * when blank, but {@code address} and {@code city} have no pattern, so a
243	     * whitespace-only value would otherwise slip through.
244	     *
245	     * @param ownerFieldsDto the submitted owner fields
246	     * @throws RequiredFieldsMissingException if any required field is missing or blank
247	     */
248	    /**
249	     * Common street-type abbreviations expanded during address normalization. Keys are the
250	     * upper-cased abbreviation tokens; values are their canonical expansions.
251	     */
252	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
253	        "ST", "STREET",
254	        "RD", "ROAD",
255	        "AVE", "AVENUE");
256	
257	    /**
258	     * Normalizes the submitted address on create and writes the canonical value back onto the
259	     * request so it is persisted, echoed back, and used for every downstream address comparison
260	     * (household duplicate detection and the household id). The value is trimmed, internal
261	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
262	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
263	     * {@code null} address is left untouched so the required-field check can report it as missing.
264	     *
265	     * @param ownerFieldsDto the submitted owner fields
266	     */
267	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
268	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
269	    }
270	
271	    /**
272	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
273	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
274	     * expanded to its full form. A {@code null} value is returned unchanged.
275	     *
276	     * @param raw the address to canonicalize, possibly {@code null}
277	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
278	     */
279	    private static String normalizeAddress(String raw) {
280	        if (raw == null) {
281	            return null;
282	        }
283	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
284	        if (collapsed.isEmpty()) {
285	            return collapsed;
286	        }
287	        String[] tokens = collapsed.split(" ");
288	        StringBuilder sb = new StringBuilder(collapsed.length());
289	        for (int i = 0; i < tokens.length; i++) {
290	            if (i > 0) {
291	                sb.append(' ');
292	            }
293	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
294	        }
295	        return sb.toString();
296	    }
