317	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
318	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
319	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
320	     */
321	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
322	        "NSW", new int[] {2000, 2099},
323	        "VIC", new int[] {3000, 3099},
324	        "QLD", new int[] {4000, 4099});
