327	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
328	     * {@code null} value is accepted. When present it has already been constrained to four digits
329	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
330	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
331	     * the postcode must fall within that region's inclusive range
332	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
333	     *
334	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
335	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
336	     *                                  city's region
337	     */
338	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
339	        String postcode = ownerFieldsDto.getPostcode();
340	        if (postcode == null) {
341	            return;
342	        }
343	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
344	            .regionFor(ownerFieldsDto.getCity());
345	        int[] range = REGION_POSTCODE_RANGE.get(region);
346	        if (range == null) {
