357	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
358	     * and echoed back in that form.
359	     *
360	     * @param ownerFieldsDto the submitted owner fields
361	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
362	     *                                        valid E.164 number
363	     */
364	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
365	        String e164 = toE164(ownerFieldsDto.getTelephone());
