372	    /**
373	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
374	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
375	     * and country code are present they are kept; otherwise country code {@code '+61'} is
376	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
377	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
378	     * the national-number length must match the country: {@code '+61'} (Australia) requires
379	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
380	     *
381	     * @param raw the submitted telephone, possibly {@code null}
382	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
383	     */
384	    private static String toE164(String raw) {
385	        if (raw == null) {
386	            return null;
387	        }
388	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
389	        String digits;
390	        if (cleaned.startsWith("+")) {
391	            digits = cleaned.substring(1);
392	        } else {
393	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
394	            digits = "61" + national;
395	        }
396	        if (!digits.matches("[0-9]{8,15}")) {
397	            return null;
398	        }
399	        if (digits.startsWith("61")) {
400	            // Australia: exactly 9 national digits after the '+61' country code.
401	            if (digits.length() - 2 != 9) {
402	                return null;
403	            }
404	        } else if (digits.startsWith("1")) {
405	            // NANP: exactly 10 national digits after the '+1' country code.
406	            if (digits.length() - 1 != 10) {
407	                return null;
408	            }
409	        }
410	        return "+" + digits;
411	    }
