423	    /**
424	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
425	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
426	     * the parts may contain whitespace or a second {@code @}.
427	     */
428	    private static final Pattern EMAIL_PATTERN =
429	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
430	
431	    /**
432	     * Disposable email domains that are not accepted for an owner's email. A create whose email
433	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
434	     * rejected. Kept lower-cased to match the normalized email.
435	     */
436	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
437	        "mailinator.com",
438	        "tempmail.com",
439	        "guerrillamail.com");
440	
441	    /**
442	     * Normalizes the submitted email when present: the value is trimmed, required to be a
443	     * syntactically valid address, required not to use a disposable-email domain, and written back
444	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
445	     * left untouched — the field is optional.
446	     *
447	     * @param ownerFieldsDto the submitted owner fields
448	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
449	     *                               valid, or its domain is on the disposable-domain blocklist
450	     */
451	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
452	        String email = ownerFieldsDto.getEmail();
453	        if (email == null) {
454	            return;
455	        }
456	        String trimmed = email.strip();
457	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
458	            throw new InvalidEmailException(email);
459	        }
460	        String normalized = trimmed.toLowerCase(Locale.ROOT);
461	        String domain = normalized.substring(normalized.indexOf('@') + 1);
462	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
463	            throw new InvalidEmailException(email);
464	        }
465	        ownerFieldsDto.setEmail(normalized);
466	    }
