468	    /**
469	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
470	     * date. A registration may be back-dated but never post-dated. The check is made against the
471	     * value as supplied, before any defaulting or business-day roll (see
472	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
473	     * to the server date).
474	     *
475	     * @param ownerFieldsDto the submitted owner fields
476	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
477	     *                                         after the server's current date
478	     */
479	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
480	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
481	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
