486	    /**
487	     * Establishes the effective registration date on create and rolls it onto a business day.
488	     * When the client does not supply a {@code registrationDate} it defaults to the server's
489	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
490	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
491	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
492	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
493	     * the membership number's year segment and the daily create-limit).
494	     *
495	     * @param ownerFieldsDto the submitted owner fields
496	     */
497	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
498	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
499	        if (effective == null) {
500	            effective = LocalDate.now();
501	        }
502	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
503	    }
