505	    /**
506	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
507	     * following Monday; any weekday is returned unchanged.
508	     *
509	     * @param date the date to adjust
510	     * @return the same date when it is a weekday, otherwise the next Monday
511	     */
512	    private static LocalDate toBusinessDay(LocalDate date) {
513	        return switch (date.getDayOfWeek()) {
514	            case SATURDAY -> date.plusDays(2);
515	            case SUNDAY -> date.plusDays(1);
516	            default -> date;
517	        };
518	    }
