521	     * Assigns the owner's {@code customerCode} on create, formatted
522	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
523	     * (preferring the postcode range, falling back to the city — the same derivation that yields
524	     * the owner's {@code locality}, see
525	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
526	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
527	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
528	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
529	     * customer code only when their normalized telephone and last name both match.
530	     *
531	     * @param owner the owner being created (with its {@code postcode}, {@code city},
532	     *              {@code telephone} and {@code lastName} already set)
533	     */
534	    private void assignCustomerCode(Owner owner) {
535	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
536	            .regionFor(owner.getPostcode(), owner.getCity());
537	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
538	            .substring(0, 8).toUpperCase(Locale.ROOT);
539	        owner.setCustomerCode(region + "-" + hash8);
