556	    /**
557	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
558	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
559	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
560	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
561	     * every owner sharing a last name and postcode receives the same value, independent of create
562	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
563	     * (which folds it into the identity key for duplicate detection) and
564	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
565	     *
566	     * @param lastName the owner's last name
567	     * @param postcode the owner's postcode, possibly {@code null}
568	     * @return the derived household id
569	     */
570	    private static String householdIdFor(String lastName, String postcode) {
571	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
572	        return sha256Hex(key).substring(0, 12);
573	    }
