575	    /**
576	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
577	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
578	     * the request opts in via {@code sharesHousehold}. Because the household is keyed on
579	     * {@code (lastName, postcode)}, a second owner sharing both is the same household: it is
580	     * rejected with a 409 as a household duplicate unless it declares {@code sharesHousehold}, in
581	     * which case it is created as a declared household member. The scan is taken over the existing
582	     * owners before this one is persisted.
583	     *
584	     * @param ownerFieldsDto the submitted owner fields ({@code lastName} and {@code postcode} set)
585	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
586	     *                                     request did not opt in via {@code sharesHousehold}
587	     */
588	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
589	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
590	            return;
