592	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
593	        boolean duplicate = this.clinicService.findAllOwners().stream()
594	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
595	        if (duplicate) {
596	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
597	        }
598	    }
