3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} from its postcode and city. The postcode
7	 * range is preferred: it is looked up against the fixed region ranges first, and
8	 * only when the postcode is absent or falls in no known range does the derivation
9	 * fall back to the fixed city-to-region table. Kept out of the mapper interface
10	 * deliberately: MapStruct treats any single-argument method on a {@code @Mapper}
11	 * interface as a candidate mapping method, so a {@code String -> String} helper
12	 * there would be applied to every String property. This static lookup is
13	 * referenced only from an explicit mapping expression instead.
14	 */
15	public final class LocalityLookup {
16	
17	    /** City -> canonical region; an exact, case-sensitive mapping. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	        "Sydney", "NSW",
20	        "Melbourne", "VIC",
21	        "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    private LocalityLookup() {
30	    }
31	
32	    /**
33	     * Returns the canonical region for {@code city} from the fixed table, or
34	     * {@code 'UNKNOWN'} when the city is not in the table.
35	     *
36	     * @param city the owner's city, possibly {@code null}
37	     * @return the canonical region, or {@code 'UNKNOWN'} if the city is unknown
38	     */
39	    public static String regionFor(String city) {
40	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
41	    }
42	
43	    /**
44	     * Returns the canonical region, preferring the postcode over the city. The
45	     * postcode is matched against the fixed region ranges first; only when it is
46	     * absent or in no known range does the lookup fall back to the city table.
47	     * This yields the same region for known cities but disambiguates cities that
48	     * share a name.
49	     *
50	     * @param postcode the owner's postcode, possibly {@code null}
51	     * @param city the owner's city, possibly {@code null}
52	     * @return the canonical region, or {@code 'UNKNOWN'} if neither resolves
53	     */
54	    public static String regionFor(String postcode, String city) {
55	        String fromPostcode = regionForPostcode(postcode);
56	        return fromPostcode != null ? fromPostcode : regionFor(city);
57	    }
58	
59	    /**
60	     * Returns the canonical region whose postcode range contains {@code postcode},
61	     * or {@code null} when the postcode is absent, non-numeric, or in no known range.
62	     */
63	    private static String regionForPostcode(String postcode) {
64	        if (postcode == null) {
65	            return null;
66	        }
67	        int value;
68	        try {
69	            value = Integer.parseInt(postcode.trim());
70	        }
71	        catch (NumberFormatException ex) {
72	            return null;
73	        }
74	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
75	            int[] range = entry.getValue();
76	            if (value >= range[0] && value <= range[1]) {
77	                return entry.getKey();
78	            }
79	        }
80	        return null;
81	    }
82	}
